operation.add:
if ($this->user->hasPermission('access', 'extension/module/shiprocket')) {
  $data['menus'][] = array(
    'id'       => 'menu-shiprocket',
    'icon'     => 'fa-truck',
    'name'     => 'Shiprocket',
    'href'     => '',
    'children' => array(
      array(
        'name' => 'Orders',
        'href' => $this->url->link(
          'extension/module/shiprocket',
          'user_token=' . $this->session->data['user_token'] . '&tab=orders',
          true
        )
      ),
      array(
        'name' => 'Settings',
        'href' => $this->url->link(
          'extension/module/shiprocket',
          'user_token=' . $this->session->data['user_token'],
          true
        )
      )
    )
  );
}
